<div class="table-panel"><table><thead><tr><th>Order</th><th>Supplier</th><th>Date</th><th>Payment</th><th>Fulfillment</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a class="strong-link" href="/order?id=<?= $o['id'] ?>">#<?= str_pad($o['id'],5,'0',STR_PAD_LEFT) ?> ↗</a></td><td><?= e($o['supplier']) ?></td><td><?= e(substr($o['created_at'],0,10)) ?></td><td><span class="badge <?= $o['payment_status']==='demo_paid'?'demo-badge':'soft-badge' ?>"><?= e(str_replace('_',' ',$o['payment_status'])) ?></span></td><td><?= e(str_replace('_',' ',$o['status'])) ?><small><?= e($o['fulfillment']) ?></small></td><td><strong><?= money($o['total']) ?></strong></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="empty-state"><h3>No orders yet</h3><p>Your next business opportunity is waiting.</p><a href="/catalog" class="btn btn-primary">Explore the marketplace</a></div><?php endif;?></div>
